head.script:
// scwin.vScrenID = "ULDFIS00100_P1.gfm";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function(e) {
    try {
        // 초기화함수
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    ibx_comAbbrv.focus();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ibx_coSnm_onkeydown
 * @description ibx_coSnm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ibx_coSnm_onkeydown = function(e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.ibx_coSnm_onkeydown" });
    }
};

/**
 * @method
 * @name btn_stdIndCd_onclick
 * @description btn_stdIndCd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_stdIndCd_onclick = function() {
    try {
        // 업종검색 팝업 오픈
        scwin.fn_StdIndSrchOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.btn_stdIndCd_onclick" });
    }
};

/**
 * @method
 * @name btn_affCoCd_onclick
 * @description btn_affCoCd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_affCoCd_onclick = function() {
    try {
        // 기업집단검색 팝업 오픈
        scwin.fn_AffCoCdSrchOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.btn_affCoCd_onclick" });
    }
};

/**
 * @method
 * @name ibx_entprGrpNm_onkeydown
 * @description ibx_entprGrpNm 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.ibx_entprGrpNm_onkeydown = function() {
    try {
        // 기업집단검색 팝업 오픈
        if (event.keyCode === 13) {
            scwin.fn_AffCoCdSrchOpen();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.ibx_entprGrpNm_onkeydown" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Search_onclick = function (e) {
    try {
        // 조회 버튼 클릭
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.img_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_Search_onkeydown = function (e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name grd_IsuInst_oncelldblclick
 * @description grd_IsuInst 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.setParam(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF99001.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name sbm_comList_submitdone
 * @description comList 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_comList_submitdone = function (e) {
    // if (dlt_comListRes.errorMsg) {
    //     alert(dlt_comListRes.errorMsg);
    // } else {
    //     tbx_totCnt.setValue("총 " + rowcount + " 건");
    // }
    dlt_comListRes.setJSON(e.responseJSON.body);
    tbx_totCnt.setValue(dlt_comListRes.getRowCount());
};

/**
 * @method
 * @name sbm_isurList_submitdone
 * @description isurList 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_isurList_submitdone = function (e) {
    dataResList.setJSON(e.responseJSON.body);
    txb_TotCnt.setValue(dataResList.getRowCount());
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dataResList.removeAll();
    txb_TotCnt.setValue("0");
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.

};

/**
 * @method
 * @name search
 * @description 기업목록 조회
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {

    }

    const reqMap = {
        comNm: ibx_comAbbrv.getValue() // 기업명
    };
    $c.sbm.execute(sbm_isurList, reqMap);
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {

    if (v_Currow === undefined) {
        v_Currow = dataResList.getRowPosition();
    }

    const res = dataResList.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};
